package com.ds.goroute.repository.impl;import com.ds.goroute.entity.PartnerPlace;import com.ds.goroute.mapper.PartnerPlaceMapper;import com.ds.goroute.repository.PartnerPlaceRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Repository;import java.time.LocalDateTime;import java.util.*;
@Repository @RequiredArgsConstructor public class PartnerPlaceRepositoryImpl implements PartnerPlaceRepository {private final PartnerPlaceMapper m;public int insertCanonical(PartnerPlace v){return m.insertCanonical(v);}public int updateCanonical(PartnerPlace v){return m.updateCanonical(v);}public int insertSource(UUID id,UUID p,UUID o,LocalDateTime n){return m.insertSource(id,p,o,n);}public int insertSnapshot(UUID id,UUID s,String p,LocalDateTime n){return m.insertSnapshot(id,s,p,n);}public Optional<UUID> findSource(UUID p,UUID o){return Optional.ofNullable(m.findSource(p,o));}public Optional<PartnerPlace> find(UUID id,UUID o){return Optional.ofNullable(m.find(id,o));}public List<PartnerPlace> findByOrganization(UUID o){return m.findByOrganization(o);}}
